const B=globalThis.BABYLON,TAU=Math.PI*2,clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export function rotorBlend(omega,bladeCount,frameSeconds){const coverage=Math.abs(omega)*Math.max(0,frameSeconds)*bladeCount/TAU,t=clamp((coverage-.18)/.30,0,1);return t*t*(3-2*t);}
function bladeAncestor(mesh,rotor){let node=mesh.parent,blade=null;while(node&&node!==rotor){if(/blade/i.test(node.name))blade=node;node=node.parent;}return blade;}
function blurDisc(scene,parent,radius,type){const mesh=new B.Mesh('propeller shutter blur',scene),positions=[],colors=[],indices=[],normals=[],rings=[.16,.27,.70,.90,1.015],opacity=[.02,.16,.14,.10,0],segments=96,tip=B.Color3.FromHexString(type==='swift'?'#efbc6b':'#d9d781'),carbon=B.Color3.FromHexString('#626d6a');
 for(let ring=0;ring<rings.length;ring++)for(let i=0;i<=segments;i++){const a=i/segments*TAU,r=rings[ring]*radius,c=ring>=3?tip:carbon;positions.push(Math.cos(a)*r,Math.sin(a)*r,.01);normals.push(0,0,1);colors.push(c.r,c.g,c.b,opacity[ring]);if(ring&&i){const at=ring*(segments+1)+i,prev=at-segments-1;indices.push(at-1,at,prev,at-1,prev,prev-1);}}
 const data=new B.VertexData();data.positions=positions;data.indices=indices;data.normals=normals;data.colors=colors;data.applyToMesh(mesh);scene.rotorBlurMaterial??=new B.StandardMaterial('rotor exposure',scene);const mat=scene.rotorBlurMaterial;mat.backFaceCulling=false;mat.disableDepthWrite=true;mat.disableLighting=true;mat.emissiveColor=B.Color3.White();mat.alpha=.9;mesh.material=mat;mesh.hasVertexAlpha=true;mesh.isPickable=false;mesh.receiveShadows=false;mesh.parent=parent;mesh.visibility=0;mesh.setEnabled(false);return mesh;
}
export function prepareRotors(plane){plane.rotors=[];for(const node of plane.surfaces.props){const blades=node.getChildMeshes(false).filter(mesh=>!mesh.isDisposed()&&bladeAncestor(mesh,node)),roots=new Set(blades.map(mesh=>bladeAncestor(mesh,node)));let disc=null;if(blades.length){node.computeWorldMatrix(true);const inverse=node.getWorldMatrix().clone().invert();let radius=0;for(const mesh of blades){mesh.computeWorldMatrix(true);const matrix=mesh.getWorldMatrix().multiply(inverse),vertices=mesh.getVerticesData(B.VertexBuffer.PositionKind);for(let i=0;i<vertices.length;i+=3){const v=B.Vector3.TransformCoordinates(new B.Vector3(vertices[i],vertices[i+1],vertices[i+2]),matrix);radius=Math.max(radius,Math.hypot(v.x,v.y));}mesh.metadata??={};mesh.metadata.rotorBlade=true;}disc=blurDisc(node.getScene(),node,radius,plane.type);}
 plane.rotors.push({node,blades,disc,bladeCount:roots.size||1,omega:0,phase:node.rotation.z,blend:0});}}
export function advanceRotors(plane,dt,state,inspection=false){if(!plane.rotors)prepareRotors(plane);const step=Math.max(0,dt);if(!Number.isFinite(step)||!step)return;for(const rotor of plane.rotors){const throttle=clamp(state.throttle||0,0,1),target=inspection?3:throttle>.002?16+throttle*125:Math.min(22,(state.speed||0)*.06),fade=1-Math.exp(-step*6),angle=target*step+(rotor.omega-target)*fade/6;rotor.omega+=(target-rotor.omega)*fade;rotor.phase=(rotor.phase+angle)%TAU;rotor.node.rotation.z=rotor.phase;rotor.blend=inspection?0:rotor.blend+(rotorBlend(rotor.omega,rotor.bladeCount,step)-rotor.blend)*(1-Math.exp(-step*12));if(rotor.disc){rotor.disc.setEnabled(rotor.blend>.005);rotor.disc.visibility=rotor.blend;for(const mesh of rotor.blades)mesh.visibility=1-rotor.blend*.94;}}}
export function stopRotors(plane){for(const rotor of plane.rotors||[]){rotor.omega=0;rotor.blend=0;rotor.disc?.setEnabled(false);for(const mesh of rotor.blades)mesh.visibility=1;}}

// Rendering stays on every display refresh. Adapt pixel/shadow resolution toward a 16.7 ms budget.
export class RenderBudget{
 constructor(pixelRatio=1){this.maximum=Math.min(1.5,Math.max(.7,pixelRatio));this.ratio=this.maximum;this.reset();}
 reset(){this.elapsed=0;this.frames=0;this.slow=0;this.fast=0;this.fps=null;this.frameMs=1000/60;this.changed=false;}
 sample(dt){this.changed=false;if(!Number.isFinite(dt)||dt<=0){this.reset();return false;}const sample=Math.min(dt,.25);this.elapsed+=dt;this.frames++;this.frameMs+=(sample*1000-this.frameMs)*(1-Math.exp(-sample*3));this.slow=this.frameMs>17.6?this.slow+sample:Math.max(0,this.slow-sample*2);this.fast=this.frameMs<16.95?this.fast+sample:0;if(this.elapsed>=1){this.fps=Math.round(this.frames/this.elapsed);this.elapsed=this.frames=0;}let ratio=this.ratio;if(this.slow>1.3){ratio=Math.max(.7,this.ratio*.9);this.slow=this.fast=0;}else if(this.fast>10){ratio=Math.min(this.maximum,this.ratio/ .9);this.slow=this.fast=0;}if(Math.abs(ratio-this.ratio)>.001){this.ratio=ratio;this.changed=true;}return this.changed;}
 apply(engine,shadow=null){engine.setHardwareScalingLevel(1/this.ratio);if(shadow){const size=this.ratio<.85?768:this.ratio<1.1?1024:1536,map=shadow.getShadowMap();if(map.getSize().width!==size)map.resize(size);shadow.filteringQuality=this.ratio<.85?B.ShadowGenerator.QUALITY_LOW:B.ShadowGenerator.QUALITY_MEDIUM;}}
}
